/**
 * HR Robots - Combined JavaScript for Performance
 * This file combines custom.js functionality
 */

// Check if jQuery is loaded
if (typeof jQuery === 'undefined') {
    console.error('jQuery is not loaded. Please ensure jquery-3.4.1.min.js is loaded before custom.js');
}

// nav menu style and year display
(function($) {
    'use strict';
    
    // Check if elements exist before binding events
    var nav = $("#navbarSupportedContent");
    var btn = $(".custom_menu-btn");
    
    if (btn.length > 0 && nav.length > 0) {
        btn.click(function (e) {
            e.preventDefault();
            nav.toggleClass("lg_nav-toggle");
            
            var menuBtn = document.querySelector(".custom_menu-btn");
            if (menuBtn) {
                menuBtn.classList.toggle("menu_btn-style");
            }
        });
    }
    
    // Get and display current year
    function getCurrentYear() {
        try {
            var d = new Date();
            var currentYear = d.getFullYear();
            var displayDate = $("#displayDate");
            
            if (displayDate.length > 0) {
                displayDate.html(currentYear);
            }
        } catch (error) {
            console.error('Error getting current year:', error);
        }
    }
    
    // Initialize on document ready
    $(document).ready(function() {
        getCurrentYear();
    });
    
})(jQuery);
